export function initPredictive({THREE,model,reduced}){
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const systems=[
['Multispectral Vision','High-resolution optical sensors monitor spacecraft surfaces for deformation, impact damage, discoloration, deployment problems, and structural changes.','Surface degradation|Micrometeoroid damage|Solar panel defects|Mechanical misalignment',[0,.1,1.2],'vision'],
['Thermal Diagnostics','Thermal imaging detects abnormal heat patterns that may indicate failing electronics, battery problems, friction, electrical resistance, or degraded systems.','Battery overheating|Electronics degradation|Thermal-control failure|Unexpected heating',[.5,.2,1.2],'thermal'],
['Precision Mapping','LiDAR measures spacecraft geometry and component position to detect structural changes, deployment issues, and physical deformation.','Structural movement|Panel deformation|Antenna misalignment|Deployment anomalies',[-.5,.4,1.15],'mapping'],
['Mechanical Health Monitoring','Close-range sensing can identify abnormal vibration patterns associated with reaction wheels, actuators, bearings, and rotating equipment.','Reaction wheel degradation|Bearing wear|Mechanical imbalance|Actuator failure',[0,.95,0],'vibration'],
['Propulsion Health','Ouranos evaluates propulsion behavior and performance for declining efficiency, abnormal thrust, leaks, and control issues.','Propellant leakage|Thruster degradation|Valve problems|Unexpected thrust',[1.95,.1,.9],'propulsion'],
['Power Intelligence','Solar generation, battery performance, charging behavior, and electrical loads reveal degradation before power becomes mission-critical.','Battery degradation|Array underperformance|Unexpected load|Charging anomalies',[-1.3,.24,-.7],'power'],
['Environmental Risk','Ouranos combines spacecraft health with surrounding orbital conditions to put each anomaly in context.','Debris conjunctions|Radiation exposure|Solar activity|Thermal cycles|Orbital conditions',[0,.9,-.6],'environment'],
['Close-Range Inspection','When remote sensing finds a suspicious component, the arm can inspect from centimeters away, capture detailed imagery, and interact with serviceable hardware.','Detailed inspection|Sensor placement|Component testing|Manipulation|Future repair',[.68,.95,.65],'arm'],
['Autonomous Rendezvous','The vehicle approaches spacecraft, maintains safe proximity, and positions itself around the asset to investigate suspected failures.','Relative navigation|Safe proximity|Target tracking|Inspection positioning',[-1.95,.1,.9],'navigation']];
let selected=0,highlight=()=>{};
const waveform='<svg viewBox="0 0 300 64"><path class="normal-wave" d="M0 32Q10 12 20 32T40 32T60 32T80 32T100 32T120 32T140 32T160 32T180 32T200 32T220 32T240 32T260 32T280 32T300 32"/><path class="abnormal-wave" d="M0 32L12 30 18 6 24 57 32 22 42 36 53 30  sixty 30 M60 32L74 32 80 4 87 60 96 15 104 42 115 32 132 32 145 8 151 59 163 16 173 40 190 32 210 32 220 3 230 62 240 18 253 38 270 32 300 32"/></svg>'.replace(' sixty 30','');
function choose(i){selected=i;const [title,desc,signals,,kind]=systems[i];$('#system-number').textContent='OBSERVATION / '+String(i+1).padStart(2,'0');$('#system-title').textContent=title;$('#system-description').textContent=desc;$('#system-signals').innerHTML=signals.split('|').map(x=>`<span>${x}</span>`).join('');all('[data-system]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.system===i));let v='';
if(kind==='vibration')v=waveform+'<p>BASELINE → INCREASING VIBRATION</p>';
else if(kind==='power')v='<div class="power-trend">94% → 92% → 88% → 82%</div><p>Degradation trend detected.</p>';
else if(kind==='propulsion')v='<svg viewBox="0 0 300 64"><path d="M0 15L50 17 100 23 150 28 200 42 250 46 300 58"/></svg><p>RELATIVE THRUST EFFICIENCY / DECLINING TREND</p>';
else if(kind==='thermal')v='<div class="thermal-scale"></div><p>LOCALIZED HEATING / INSPECT COMPONENT</p>';
else if(kind==='environment')v='<div class="orbit-mini"><i></i><b></b></div><p>ENVIRONMENT + SPACECRAFT HEALTH</p>';
else if(kind==='navigation')v='<div class="trajectory"><i></i></div><p>AUTONOMOUS APPROACH / SAFE PROXIMITY</p>';
else if(kind==='mapping')v='<div class="mapping-grid"></div><p>GEOMETRY DEVIATION / COMPARE BASELINE</p>';
else if(kind==='arm')v='<p class="power-trend">REMOTE SIGNAL → CLOSE-RANGE EVIDENCE</p>';
else v='<div class="panel-scan"></div><p>OPTICAL SCAN / SURFACE CHANGE DETECTION</p>';
$('#system-visual').innerHTML=v;highlight();
}
systems.forEach((s,i)=>{const b=document.createElement('button');b.dataset.system=i;b.textContent=String(i+1).padStart(2,'0')+' / '+s[0];b.addEventListener('click',()=>choose(i));$('.subsystem-nav').append(b);const h=document.createElement('button');h.className='model-hotspot';h.dataset.system=i;h.setAttribute('aria-label',s[0]);h.innerHTML=`<span>${i+1}</span><em>${s[0]}</em>`;h.addEventListener('click',()=>choose(i));$('#hotspots').append(h);});choose(0);
// Controls stay deterministic; these weights illustrate relative risk, not a flight model.
let score=14,shownScore=14,simToken=0,simBusy=false;
function risk(){const v=Object.fromEntries(all('[data-risk]').map(e=>[e.dataset.risk,+e.value]));all('[data-risk]').forEach(e=>$('#out-'+e.dataset.risk).textContent=e.value+'%');score=Math.min(100,Math.round(14+(97-v.battery)*.30+v.thermal*.25+v.vibration*.75+(100-v.solar)*.34+(100-v.propulsion)*.3+v.debris*.12));score=Math.max(0,score);$('#risk-level').textContent=score>=80?'CRITICAL':score>=60?'ELEVATED RISK':score>=30?'WATCH':'NOMINAL';const issue=v.vibration>20?'Possible reaction wheel degradation.':v.battery<80?'Battery degradation trend.':v.solar<90?'Solar generation underperformance.':v.propulsion<80?'Propulsion efficiency declining.':v.thermal>25?'Thermal anomaly requires review.':v.debris>40?'Environmental exposure increasing.':'No significant degradation trend.';$('#risk-issue').textContent=issue;$('#risk-action').textContent=score>=60?'Recommended action: dispatch inspection vehicle.':score>=30?'Recommended action: increase observation cadence.':'Recommended action: continue monitoring.';$('#risk-bar').style.width=score+'%';$('#risk-probability').textContent=score>=60?'Illustrative fault probability: '+Math.max(0,score-4)+'%':'Estimated fault likelihood: '+(score>=30?'increasing':'low');$('#risk-window').textContent=score>=60?'Illustrative critical-condition window: 14–21 days':'No critical-condition window identified';simToken++;simBusy=false;$('#simulate-inspection').disabled=false;$('#mini-mission').hidden=true;}
all('[data-risk]').forEach(e=>e.addEventListener('input',risk));
function preset(elevated){for(const [k,v] of Object.entries({battery:97,thermal:elevated?100:0,vibration:elevated?38:0,solar:100,propulsion:100,debris:0}))$('#risk-'+k).value=v;risk();}
$('#risk-normal').onclick=()=>preset(false);$('#risk-elevated').onclick=()=>preset(true);
$('#simulate-inspection').onclick=()=>{const token=++simToken;simBusy=true;$('#simulate-inspection').disabled=true;$('#mini-mission').hidden=false;$('#sim-result').textContent='OSV-03 dispatched / approaching spacecraft.';const start=performance.now(),wheel=+$('#risk-vibration').value>20;function step(now){if(token!==simToken)return;const t=Math.min(1,(now-start)/3200),x=15+265*Math.min(1,t*1.5),y=35-45*Math.sin(Math.min(1,t*1.5)*Math.PI/2)+33*Math.min(1,t*1.5);$('#sim-vehicle').setAttribute('transform',`translate(${x} ${y})`);if(t>.65)$('#sim-result').textContent='Close-range scan / correlating sensor evidence…';if(t<1)requestAnimationFrame(step);else{simBusy=false;$('#simulate-inspection').disabled=false;$('#sim-result').textContent=wheel?'SIMULATED RESULT: Reaction wheel anomaly confirmed. Confidence: 87%. Recommended response: preventive servicing.':score>=30?'SIMULATED RESULT: Component anomaly localized. Additional observations support preventive servicing and operator review.':'SIMULATED RESULT: No significant fault confirmed. Continue monitoring and update the health baseline.';$('.risk-console').scrollTo({top:$('.risk-console').scrollHeight,behavior:reduced?'instant':'smooth'});}}requestAnimationFrame(step);};risk();
const flow=[['SPACECRAFT DATA',21,'Solar output drifts.','Output falls 7%. The mission is still operating.'],['OURANOS AI',34,'Signals begin to align.','Temperature and attitude-control demand rise. Historical patterns resemble early deployment-mechanism degradation.'],['RISK SCORE',51,'Increasing failure probability.','Multiple weak signals raise risk. No exact failure date is assumed.'],['AUTONOMOUS INSPECTION',67,'Inspection recommended.','A servicing vehicle collects visual and thermal evidence before the fault becomes critical.'],['UPDATED DIAGNOSIS',67,'Probable actuator degradation.','Abnormal heating near the deployment mechanism. Illustrative confidence: 81%.'],['INTERVENTION',67,'Service before the next high-load cycle.','Preventive intervention addresses the suspected cause. Subsequent observation verifies the result.']];
let flowTimer;function flowStage(i){const f=flow[i];$('#flow-score').textContent=f[1];$('#flow-title').textContent=f[2];$('#flow-copy').textContent=f[3];$('#flow-progress').style.width=(i+1)/6*100+'%';all('[data-flow]').forEach((b,j)=>b.setAttribute('aria-current',j===i?'step':'false'));}
flow.forEach((f,i)=>{const b=document.createElement('button');b.dataset.flow=i;b.textContent=f[0];b.onclick=()=>{clearInterval(flowTimer);$('#play-flow').disabled=false;flowStage(i)};$('#flow-steps').append(b)});flowStage(0);
$('#play-flow').onclick=()=>{clearInterval(flowTimer);let i=0;flowStage(0);$('#play-flow').disabled=true;flowTimer=setInterval(()=>{flowStage(++i);if(i===5){clearInterval(flowTimer);$('#play-flow').disabled=false;}},2000)};
let fleetStart=0;$('#fleet-play').onclick=()=>{fleetStart=performance.now();$('#fleet-play').disabled=true;};
// A dedicated mission-sensing view uses the same model and materials as the flight scene.
let vr,vs,vc,vm,arm,grid,scanPlane,thermal;let yaw=-.35,pitch=.18,panX=0,panY=0,zoom=7.4,drag=null;
try{vr=new THREE.WebGLRenderer({alpha:true,antialias:true});vr.setPixelRatio(Math.min(devicePixelRatio,1.5));$('#vehicle-canvas').append(vr.domElement);vs=new THREE.Scene();vc=new THREE.PerspectiveCamera(42,1,.1,100);vc.position.z=zoom;vs.add(new THREE.HemisphereLight(0xe3f3ff,0x23384d,3));const sun=new THREE.DirectionalLight(0xffffff,3);sun.position.set(3,5,8);vs.add(sun);vm=model.clone(true);vm.position.set(0,0,0);vm.rotation.set(pitch,yaw,0);vm.traverse(o=>{if(o.isMesh)o.material=o.material.clone();});vs.add(vm);highlight=()=>{const point=new THREE.Vector3(...systems[selected][3]);vm.traverse(o=>{if(o.isMesh&&o.material.emissive){const position=new THREE.Vector3();o.getWorldPosition(position);vm.worldToLocal(position);const near=position.distanceTo(point)<.65;o.material.emissive.setHex(near?(selected===1?0x9a270d:0x215e78):0x000000);o.material.emissiveIntensity=near?.5:0;}});};highlight();arm=vm.children.find(o=>o.isGroup&&Math.abs(o.position.x-.68)<.01);
grid=new THREE.GridHelper(6,18,0xa1d9eb,0x497b94);grid.position.y=-1.25;vs.add(grid);
thermal=new THREE.Mesh(new THREE.SphereGeometry(.29,20,12),new THREE.MeshBasicMaterial({color:0xff733d,transparent:true,opacity:.85}));thermal.position.set(.5,.2,1.25);vm.add(thermal);
scanPlane=new THREE.Mesh(new THREE.PlaneGeometry(1.7,1.2),new THREE.MeshBasicMaterial({color:0x5db7d7,wireframe:true,transparent:true,opacity:.45}));scanPlane.position.set(2.8,.2,-.5);vs.add(scanPlane);
const canvas=vr.domElement;canvas.tabIndex=0;canvas.setAttribute('aria-label','Rotate spacecraft with arrow keys; shift and arrows to pan.');canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const dx=e.key==='ArrowLeft'?-.1:e.key==='ArrowRight'?.1:0,dy=e.key==='ArrowUp'?-.1:e.key==='ArrowDown'?.1:0;if(e.shiftKey){panX=Math.max(-1,Math.min(1,panX+dx));panY=Math.max(-.7,Math.min(.7,panY-dy));}else{yaw+=dx;pitch=Math.max(-1,Math.min(1,pitch+dy));}}};canvas.style.touchAction='none';canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,pan:e.shiftKey};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.pan){panX=Math.max(-1,Math.min(1,panX+dx*.007));panY=Math.max(-.7,Math.min(.7,panY-dy*.007));}else{yaw+=dx*.008;pitch=Math.max(-1,Math.min(1,pitch+dy*.008));}drag.x=e.clientX;drag.y=e.clientY;};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
$('#zoom-in').onclick=()=>zoom=Math.max(5.5,zoom-.5);$('#zoom-out').onclick=()=>zoom=Math.min(10,zoom+.5);$('#reset-view').onclick=()=>{yaw=-.35;pitch=.18;panX=panY=0;zoom=7.4;};
function size(){const r=$('#vehicle-view').getBoundingClientRect();if(r.width&&r.height){vr.setSize(r.width,r.height);vc.aspect=r.width/r.height;vc.updateProjectionMatrix();}}new ResizeObserver(size).observe($('#vehicle-view'));size();
}catch(e){$('#vehicle-canvas').textContent='3D view unavailable. Explore all nine sensing systems using the controls below.';console.error(e)}
function tick(now){requestAnimationFrame(tick);shownScore+=(score-shownScore)*.09;$('#risk-score').textContent=Math.round(shownScore);if(fleetStart){const t=Math.min(1,(now-fleetStart)/6500);$('#fleet-score').textContent=Math.round(t<.55?23+55*t/.55:78);$('#fleet-status').textContent=t<.55?'SAT-2047 / increasing reaction-control risk.':t<1?'PREDICTED FAULT: Reaction control system. OSV-04 en route.':'OSV-04 / inspecting the asset before a critical event.';const u=Math.max(0,(t-.55)/.45);$('#fleet-vehicle').setAttribute('cx',35+225*u);$('#fleet-vehicle').setAttribute('cy',50-95*u+87*u*u);if(t===1){fleetStart=0;$('#fleet-play').disabled=false;}}
if(!vr||!$('#rendezvous').classList.contains('active')||document.hidden)return;vm.rotation.set(pitch,yaw,0);vm.position.set(panX,panY,0);vc.position.z=zoom;const kind=systems[selected][4];grid.visible=kind==='mapping';grid.rotation.y=reduced?0:now*.0001;thermal.visible=kind==='thermal';thermal.scale.setScalar(reduced?1:1+Math.sin(now*.004)*.08);scanPlane.visible=kind==='vision';scanPlane.position.y=reduced?.2:Math.sin(now*.002)*.35;if(arm)arm.rotation.y=kind==='arm'?(reduced?-.4:Math.sin(now*.001)*.35): -1.2;if(kind==='navigation')vm.position.x+=reduced?0:Math.sin(now*.0008)*.4;vm.updateMatrixWorld(true);all('.model-hotspot').forEach((b,i)=>{const v=new THREE.Vector3(...systems[i][3]);vm.localToWorld(v);v.project(vc);b.style.left=(v.x*.5+.5)*100+'%';b.style.top=(-v.y*.5+.5)*100+'%';});vr.render(vs,vc);
}requestAnimationFrame(tick);
}
